def transform(grid):
    """Fill cells with 3 between consecutive non-background cells (value 5) in rows and columns.

    Background color: 7
    Special color: 5 (foreground)
    Fill color: 3 (between consecutive specials)
    """
    bg = 7
    special = 5
    fill = 3

    # Make a copy to modify
    result = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Fill rows: between consecutive special cells
    for r in range(h):
        positions = [c for c in range(w) if result[r][c] == special]
        for i in range(len(positions) - 1):
            for c in range(positions[i] + 1, positions[i + 1]):
                if result[r][c] == bg:
                    result[r][c] = fill

    # Fill columns: between consecutive special cells
    for c in range(w):
        positions = [r for r in range(h) if result[r][c] == special]
        for i in range(len(positions) - 1):
            for r in range(positions[i] + 1, positions[i + 1]):
                if result[r][c] == bg:
                    result[r][c] = fill

    return result

